        slog = b[\"derived\"].get(\"scaling_log\") or {}
        print(f'  scaling_log keys={list(slog.keys())}')
        by_a = slog.get(\"by_analyzer\") or {}
        for name, recs in by_a.items():
            if recs:
                print(f'    analyzer={name} first_rec keys={list(recs[0].keys())}')
